import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import * as jobsApi from "../../api/jobs";
import type { JobDetail, JobFieldValue } from "../../types/jobs";

// The physical paper docket's own colour, reproduced exactly - this page IS that form now.
const PAGE_BG = "#f7f700";

// Letterhead marks - background removed, converted to black-and-white silhouettes so they
// photocopy/print the same way the rest of the docket's black rules and text do, instead of
// clashing with the yellow ground as full-colour art. Inlined as data URIs (not separate
// asset files) so this one component file is the whole deploy - nothing else to remember to
// include in the tarball.
const FOUR_S_LOGO = "data:image/png;base64,";
const AEO_LOGO = "data:image/png;base64,";
const CRISIL_LOGO = "data:image/png;base64,";
const FTWZ_LOGO = "data:image/png;base64,";

const FCL_OPTIONS = ["FCL", "LCL", "B.B"] as const;
const CATEGORY_OPTIONS = ["HOME CONSUMPTION", "BOND", "EX-BOND", "DEEC", "EPCG", "100% EOU", "SEZ"] as const;
const TRANSACTION_MODES = ["Deferred", "Transaction"] as const;
const PRIORITY_TYPES = ["Advance", "Prior", "Normal"] as const;

/** One row on the docket. `patterns` are tried in order against every field's label_name
 *  (case-insensitive); the first field with a matching label AND a non-empty value wins -
 *  that becomes the row's STARTING value, editable from there. A row with no patterns at
 *  all (Duty, Cleared on, Transporter Name, ...) starts blank - those are filled in by hand
 *  on the real form too, so an empty starting value is the correct, honest answer, not a
 *  missing feature. */
interface DocketRow {
  label: string;
  patterns?: RegExp[];
  /** Two labels sharing one row (Bill of Entry No. + its Date) - shown as two half-width cells. */
  pairWith?: { label: string; patterns?: RegExp[] };
}

function bestValue(fields: JobFieldValue[], patterns: RegExp[] | undefined): string {
  if (!patterns) return "";
  for (const pattern of patterns) {
    const hit = fields.find((f) => pattern.test(f.label_name) && (f.value ?? "").trim());
    if (hit) return (hit.value ?? "").trim();
  }
  return "";
}

/** Import and export shipments name a different party on this line - everything else on
 *  the docket is identical either way. */
function partyRow(isExport: boolean): DocketRow {
  return isExport
    ? { label: "Name of the Exporter", patterns: [/exporter/i, /shipper/i, /consignor/i] }
    : { label: "Name of the Importer", patterns: [/importer/i, /consignee/i, /\bbuyer\b/i] };
}

function rows(isExport: boolean): DocketRow[] {
  return [
    partyRow(isExport),
    { label: "Documents Received on" },
    { label: "HAWB BL No.", patterns: [/house.*(bl|bill|way\s*bill)/i, /\bhawb\b/i, /\bhbl\b/i] },
    { label: "MAWB BL No.", patterns: [/master.*(bl|bill|way\s*bill)/i, /\bmawb\b/i, /\bmbl\b/i] },
    { label: "Vessel Name", patterns: [/vessel/i, /flight/i] },
    { label: "Inward Date / IGM Date", patterns: [/\bigm\b/i, /inward\s*date/i, /arrival\s*date/i, /eta/i] },
    {
      label: "No. of Cartons / Pallet / Drum",
      patterns: [/no\.?\s*(of|&)?\s*(kind\s*of\s*)?(carton|pack|pallet|drum)/i, /\bcartons?\b/i, /\bpackages?\b/i],
    },
    { label: "No. of Container 20\u201d & 40\u201d / LCL", patterns: [/container/i] },
    { label: "Weight (Gross)", patterns: [/gross\s*weight/i, /\bweight\b/i] },
    { label: "Chargeable Weight", patterns: [/chargeable\s*weight/i, /\bcbm\b/i, /volume/i] },
    {
      label: "Bill of Entry No.",
      patterns: [/bill\s*of\s*entry\s*(no|number)/i, /\bboe\s*(no|number)\b/i],
      pairWith: { label: "Date", patterns: [/bill\s*of\s*entry\s*date/i, /\bboe\s*date\b/i] },
    },
    { label: "Ass. Value", patterns: [/assessable\s*value/i, /ass(essment)?\.?\s*value/i] },
    { label: "Duty" },
    { label: "Consol / Liner Delivery Order Charges" },
    { label: "INCO Terms", patterns: [/incoterm/i, /terms\s*of\s*(delivery|payment)/i] },
    { label: "Name of the CFS / Charges" },
    { label: "Cleared on" },
    { label: "Transporter Name" },
    { label: "Docket Closed on" },
    { label: "Billed on" },
    { label: "Bill No." },
  ];
}

function docketTitle(mode: string | null | undefined): string {
  return mode ? `${mode.toUpperCase()} DOCKET` : "IMPORT / EXPORT DOCKET";
}

export function EDocketPage() {
  const { jobId = "" } = useParams();
  const [job, setJob] = useState<JobDetail | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [jobNo, setJobNo] = useState("");
  const [fclLcl, setFclLcl] = useState<string | null>(null);
  const [categories, setCategories] = useState<Set<string>>(new Set());
  const [transactionMode, setTransactionMode] = useState<string>(TRANSACTION_MODES[0]);
  const [priorityType, setPriorityType] = useState<string>(PRIORITY_TYPES[2]);
  // Keyed by row label (the paired Date row uses "<label> / Date") - editable from whatever
  // was auto-mapped, or blank where nothing was.
  const [values, setValues] = useState<Record<string, string>>({});

  const isExport = /export/i.test(job?.mode ?? "");
  const docketRows = useMemo(() => rows(isExport), [isExport]);

  useEffect(() => {
    jobsApi
      .getJob(jobId)
      .then((detail) => {
        setJob(detail);
        setJobNo(detail.reference);
      })
      .catch(() => setError("Could not load this job."));
  }, [jobId]);

  // Fill starting values once the job (and therefore its field_values) is known - never
  // overwrites something the operator has already typed on a re-render.
  useEffect(() => {
    if (!job) return;
    setValues((prev) => {
      const next = { ...prev };
      for (const row of rows(isExport)) {
        if (!(row.label in next)) next[row.label] = bestValue(job.field_values, row.patterns);
        if (row.pairWith && !(row.pairWith.label + "\u0000" + row.label in next)) {
          next[row.pairWith.label + "\u0000" + row.label] = bestValue(job.field_values, row.pairWith.patterns);
        }
      }
      return next;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [job]);

  function toggleCategory(cat: string) {
    setCategories((prev) => {
      const next = new Set(prev);
      if (next.has(cat)) next.delete(cat);
      else next.add(cat);
      return next;
    });
  }

  if (error) {
    return <div className="p-8 text-sm text-rose-600">{error}</div>;
  }
  if (!job) {
    return <div className="p-8 text-sm text-slate-500">Loading\u2026</div>;
  }

  return (
    <div style={{ background: PAGE_BG, minHeight: "100vh" }} className="text-black">
      <style>{`@media print { .no-print { display: none !important; } body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } input { border: none !important; outline: none !important; background: transparent !important; } }`}</style>

      <div className="no-print flex justify-end gap-2 p-3">
        <button
          type="button"
          onClick={() => window.print()}
          title="Opens the print dialog - choose \u2018Save as PDF\u2019 as the destination to download"
          className="rounded-lg border-2 border-black px-4 py-2 text-sm font-medium hover:bg-black/5"
        >
          Download PDF
        </button>
        <button
          type="button"
          onClick={() => window.print()}
          className="rounded-lg bg-black px-4 py-2 text-sm font-medium text-white hover:bg-slate-800"
        >
          Print
        </button>
      </div>

      <div
        className="mx-auto max-w-3xl border-2 border-black p-4 font-sans text-sm"
        style={{ background: PAGE_BG }}
      >
        {/* Letterhead: logo | title+badges | address */}
        <div
          className="mb-2 grid items-center gap-x-3 gap-y-1 border-b-2 border-black pb-2"
          style={{ gridTemplateColumns: "175px 1fr 210px", gridTemplateRows: "repeat(2, auto)" }}
        >
          <div className="text-center" style={{ gridColumn: "1", gridRow: "1 / span 2" }}>
            <img src={FOUR_S_LOGO} alt="4S Logisticsolutions" className="mx-auto h-20 w-auto" />
          </div>
          <div
            className="border-2 border-black py-1.5 text-center text-lg font-bold tracking-wide"
            style={{ gridColumn: "2", gridRow: "1" }}
          >
            {docketTitle(job.mode)}
          </div>
          <div
            className="self-start leading-snug"
            style={{ fontSize: 11, gridColumn: "3", gridRow: "1 / span 2" }}
          >
            <p className="font-semibold">Old No. 53, 54, &amp; 55, First &amp; Second Floor,</p>
            <p>Rowther Chambers, Rajaji Salai, Chennai - 600 001.</p>
            <p>E-mail : imports@4slogistics.com</p>
            <p>Website : www.4slogistics.com</p>
          </div>
          <div
            className="flex items-center justify-center gap-2.5"
            style={{ gridColumn: "2", gridRow: "2" }}
          >
            <img src={AEO_LOGO} alt="AEO Indian Customs" className="h-9 w-auto" />
            <img src={FTWZ_LOGO} alt="FTWZ" className="h-6 w-auto" />
            <img src={CRISIL_LOGO} alt="CRISIL Verified" className="h-9 w-auto" />
          </div>
        </div>

        {/* Transaction Mode / Priority Type */}
        <div className="mb-2 flex flex-wrap gap-2.5">
          <div className="flex flex-1 items-center border-2 border-black" style={{ minWidth: 200 }}>
            <label className="border-r border-black px-2 py-1.5 font-bold" style={{ fontSize: 11 }}>Transaction Mode</label>
            <select
              value={transactionMode}
              onChange={(e) => setTransactionMode(e.target.value)}
              className="flex-1 bg-transparent px-2 py-1.5 font-mono text-xs font-semibold"
            >
              {TRANSACTION_MODES.map((o) => (
                <option key={o} value={o}>{o}</option>
              ))}
            </select>
          </div>
          <div className="flex flex-1 items-center border-2 border-black" style={{ minWidth: 200 }}>
            <label className="border-r border-black px-2 py-1.5 font-bold" style={{ fontSize: 11 }}>Priority Type</label>
            <select
              value={priorityType}
              onChange={(e) => setPriorityType(e.target.value)}
              className="flex-1 bg-transparent px-2 py-1.5 font-mono text-xs font-semibold"
            >
              {PRIORITY_TYPES.map((o) => (
                <option key={o} value={o}>{o}</option>
              ))}
            </select>
          </div>
        </div>

        {/* RMS/GROUP-FCA + FCL/LCL/B.B row, JOB No. row, and the tall checkbox column beside both */}
        <div
          className="mb-2 grid gap-1.5"
          style={{ gridTemplateColumns: "1fr 190px", gridTemplateRows: "repeat(2, auto)" }}
        >
          <div className="flex gap-1.5" style={{ gridColumn: "1", gridRow: "1" }}>
            <div className="flex border-2 border-black text-xs font-semibold">
              <span className="border-r border-black px-2 py-1.5">RMS</span>
              <span className="px-2 py-1.5">GROUP - FCA</span>
            </div>
            <div className="flex flex-1 border-2 border-black">
              {FCL_OPTIONS.map((o, i) => (
                <button
                  key={o}
                  type="button"
                  onClick={() => setFclLcl(o)}
                  className={`flex flex-1 items-center justify-center gap-1.5 py-1.5 text-xs font-bold ${i > 0 ? "border-l border-black" : ""}`}
                >
                  <span
                    className="flex h-3.5 w-3.5 shrink-0 items-center justify-center border border-black leading-none"
                    style={{ fontSize: 10 }}
                  >
                    {fclLcl === o ? "\u2713" : ""}
                  </span>
                  {o}
                </button>
              ))}
            </div>
          </div>
          <div
            className="flex items-center border-2 border-black px-2.5 py-1.5 font-bold"
            style={{ gridColumn: "1", gridRow: "2" }}
          >
            JOB No.&nbsp;:
            <input
              value={jobNo}
              onChange={(e) => setJobNo(e.target.value)}
              className="ml-1.5 flex-1 bg-transparent font-mono text-sm font-bold"
            />
          </div>
          <div
            className="flex flex-col border-2 border-black"
            style={{ gridColumn: "2", gridRow: "1 / span 2" }}
          >
            {CATEGORY_OPTIONS.map((o, i) => (
              <button
                key={o}
                type="button"
                onClick={() => toggleCategory(o)}
                className={`flex flex-1 items-center justify-between px-2 py-1 text-left font-semibold ${i > 0 ? "border-t border-black" : ""}`}
                style={{ fontSize: 10.5 }}
              >
                {o}
                <span
                  className="flex h-3 w-3 shrink-0 items-center justify-center border border-black leading-none"
                  style={{ fontSize: 9 }}
                >
                  {categories.has(o) ? "\u2713" : ""}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Field table - every value is editable */}
        <table className="w-full border-collapse text-sm">
          <tbody>
            {docketRows.map((row) => {
              const key = row.pairWith ? row.pairWith.label + "\u0000" + row.label : row.label;
              return (
                <tr key={row.label}>
                  <td className="border border-black px-2 py-1 align-top font-medium" style={{ width: "37%" }}>
                    {row.label}
                  </td>
                  {row.pairWith ? (
                    <>
                      <td className="border border-black px-1.5 py-1 align-top">
                        <input
                          value={values[row.label] ?? ""}
                          onChange={(e) => setValues((v) => ({ ...v, [row.label]: e.target.value }))}
                          className="w-full bg-transparent font-mono text-xs"
                        />
                      </td>
                      <td className="w-24 border border-black px-2 py-1 align-top font-medium">
                        {row.pairWith.label}
                      </td>
                      <td className="border border-black px-1.5 py-1 align-top">
                        <input
                          value={values[key] ?? ""}
                          onChange={(e) => setValues((v) => ({ ...v, [key]: e.target.value }))}
                          className="w-full bg-transparent font-mono text-xs"
                        />
                      </td>
                    </>
                  ) : (
                    <td className="border border-black px-1.5 py-1 align-top" colSpan={3}>
                      <input
                        value={values[row.label] ?? ""}
                        onChange={(e) => setValues((v) => ({ ...v, [row.label]: e.target.value }))}
                        className="w-full bg-transparent font-mono text-xs"
                      />
                    </td>
                  )}
                </tr>
              );
            })}
          </tbody>
        </table>

        <p className="mt-3 text-xs text-slate-700">
          Starting values come from what was extracted off the documents where a confident match
          was found - everything above is editable or clearable before you print. Nothing here is
          saved back to the job; this is a print/download view.
        </p>
      </div>
    </div>
  );
}
